#include <Arduino.h>
#include <BLEDevice.h>
#include <BLEServer.h>
#include <BLEUtils.h>
#include <BLE2902.h>
static BLECharacteristic* reading;
void setup() {
    BLEDevice::init("SensorDemo");
    BLEServer* server = BLEDevice::createServer();
    BLEService* service = server->createService("180A");
    reading = service->createCharacteristic("2A57", BLECharacteristic::PROPERTY_READ | BLECharacteristic::PROPERTY_NOTIFY);
    reading->addDescriptor(new BLE2902());
    reading->setValue("ready");
    service->start();
    BLEDevice::getAdvertising()->start();
}
void loop() { reading->setValue("sample"); reading->notify(); delay(1000); }

